// Polyfill worker_threads.markAsUncloneable for Node.js < 21 compatibility (specifically Node 20.20.2)
import worker_threads from "node:worker_threads";
import { WebSocket } from "ws";

if (worker_threads && !worker_threads.markAsUncloneable) {
  (worker_threads as any).markAsUncloneable = function (obj: any) {
    if (worker_threads.markAsUntransferable) {
      try {
        worker_threads.markAsUntransferable(obj);
      } catch {
        // no-op
      }
    }
  };
}

// Polyfill Promise.withResolvers for Node.js < 22 compatibility (specifically Node 20.20.2)
if (typeof Promise.withResolvers === "undefined") {
  Promise.withResolvers = function <T>() {
    let resolve!: (value: T | PromiseLike<T>) => void;
    let reject!: (reason?: any) => void;
    const promise = new Promise<T>((res, rej) => {
      resolve = res;
      reject = rej;
    });
    return { promise, resolve, reject };
  } as any;
}

// Polyfill WebSocket for Node.js < 22 compatibility (specifically Node 20.20.2)
if (typeof globalThis.WebSocket === "undefined") {
  (globalThis as any).WebSocket = WebSocket;
}

// Test-only DATA_DIR isolation.
//
// Loaded via `node --import ./tests/_setup/isolateDataDir.ts` from the test/mutation
// invocations (package.json test scripts, stryker.conf.json tap.nodeArgs, the
// quality.yml TIA step, and the CI test jobs) — NEVER from production. It MUST stay
// out of open-sse/utils/setupPolyfill.ts, which is also imported by production
// (bin/omniroute.mjs, proxyFetch.ts, proxyDispatcher.ts) where redirecting DATA_DIR
// would point the live SQLite DB at a throwaway temp dir.
//
// Why: node:test spawns a process per test file and Stryker spawns one per sandbox,
// but every process resolves DATA_DIR to the SAME default (~/.omniroute) when the env
// var is unset (see src/lib/dataPaths.ts::resolveDataDir). Concurrent processes then
// open the SAME on-disk storage.sqlite, causing cross-file state races: SQLite lock
// contention that hangs `test:unit` under high `--test-concurrency`, and the
// non-deterministic baseline that forced Stryker to `concurrency: 1`.
//
// Giving each process its own DATA_DIR under the OS temp dir removes the shared file,
// so concurrent test processes never collide. Tests that set DATA_DIR explicitly keep
// winning — this only fills in an isolated default when none was chosen.
import fs from "node:fs";
import os from "node:os";
import path from "node:path";

// File logger worker threads can outlive a test's temporary DATA_DIR cleanup and then
// raise ENOENT/ENOTEMPTY after the test has already passed. Keep the global test default
// console-only; tests that cover file logging explicitly set APP_LOG_TO_FILE themselves.
process.env.APP_LOG_TO_FILE ||= "false";

if (!process.env.DATA_DIR) {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), "omniroute-test-"));
  process.env.DATA_DIR = dir;

  // Best-effort cleanup so a long suite run does not leak hundreds of temp DBs.
  process.on("exit", () => {
    try {
      fs.rmSync(dir, { recursive: true, force: true });
    } catch {
      // ignore — the OS reaps its temp dir eventually.
    }
  });
}

// System-trust guard: the suite must NEVER mutate the OS trust store. On a
// persistent self-hosted runner the cert-flow integration test installed a fake
// 105-byte PEM into /usr/local/share/ca-certificates and update-ca-certificates
// baked it into the bundle, breaking ALL system TLS on the VM (2026-07-05).
// installCert/uninstallCert/installTproxyCa/uninstallTproxyCa no-op under this.
process.env.OMNIROUTE_SKIP_SYSTEM_TRUST = "1";

// DNS-write guard: the suite must NEVER mutate /etc/hosts. Tests that exercise
// the real MITM path call addDNSEntries(); this env var makes it a no-op.
process.env.OMNIROUTE_SKIP_DNS_WRITE = "1";

import test from "node:test";
import assert from "node:assert/strict";

import { PuterExecutor } from "../../open-sse/executors/puter.ts";

test("PuterExecutor.buildUrl always uses Puter OpenAI endpoint", () => {
  const executor = new PuterExecutor();
  assert.equal(
    executor.buildUrl("gpt-4.1", true),
    "https://api.puter.com/puterai/openai/v1/chat/completions"
  );
});

test("PuterExecutor.buildHeaders supports API key, access token and optional SSE accept", () => {
  const executor = new PuterExecutor();
  const apiKeyHeaders = executor.buildHeaders({ apiKey: "puter-key" }, true);
  const accessTokenHeaders = executor.buildHeaders({ accessToken: "puter-token" }, false);

  assert.deepEqual(apiKeyHeaders, {
    "Content-Type": "application/json",
    Authorization: "Bearer puter-key",
    Accept: "text/event-stream",
  });
  assert.deepEqual(accessTokenHeaders, {
    "Content-Type": "application/json",
    Authorization: "Bearer puter-token",
  });
});

test("PuterExecutor.transformRequest is a passthrough", () => {
  const executor = new PuterExecutor();
  const body = {
    model: "google/gemini-2.5-pro",
    messages: [{ role: "user", content: "hello" }],
  };
  assert.equal(executor.transformRequest(body.model, body, true, {}), body);
});

test("PuterExecutor.execute uses inherited BaseExecutor flow", async () => {
  const executor = new PuterExecutor();
  const originalFetch = globalThis.fetch;
  let captured;
  globalThis.fetch = async (url, options) => {
    captured = { url: String(url), options };
    return new Response(JSON.stringify({ ok: true }), {
      status: 200,
      headers: { "Content-Type": "application/json" },
    });
  };

  try {
    const body = {
      model: "google/gemini-2.5-pro",
      messages: [{ role: "user", content: "hello" }],
    };
    const result = await executor.execute({
      model: body.model,
      body,
      stream: false,
      credentials: { apiKey: "puter-key" },
    });

    assert.equal(result.response.status, 200);
    // #3941 ("Capture actual upstream provider requests") makes BaseExecutor return
    // transformedBody as the JSON-round-tripped serialized body (the real on-the-wire
    // payload, post fingerprint/sign), so it is a structurally-equal new object rather
    // than the same reference. Puter's transformRequest is still a passthrough, so the
    // body must match structurally.
    assert.deepEqual(result.transformedBody, body);
    assert.equal(result.url, "https://api.puter.com/puterai/openai/v1/chat/completions");
    assert.equal(captured.options.headers.Authorization, "Bearer puter-key");
    assert.equal(captured.options.body, JSON.stringify(body));
  } finally {
    globalThis.fetch = originalFetch;
  }
});

import { BaseExecutor } from "./base.ts";
import { PROVIDERS } from "../config/constants.ts";

/**
 * PuterExecutor — OpenAI-compatible proxy for Puter AI.
 *
 * Puter exposes 500+ models (GPT, Claude, Gemini, Grok, DeepSeek, Qwen, Mistral...)
 * through a single OpenAI-compatible REST endpoint.
 *
 * Endpoint: https://api.puter.com/puterai/openai/v1/chat/completions
 * Auth:     Bearer <puter_auth_token>  (from puter.com/dashboard → Copy Auth Token)
 * Docs:     https://docs.puter.com/AI/
 *
 * Model ID examples:
 *   OpenAI:   "gpt-4o-mini", "gpt-4o", "gpt-4.1"
 *   Claude:   "claude-sonnet-4-5", "claude-opus-4", "claude-haiku-4-5"
 *   Gemini:   "google/gemini-2.0-flash", "google/gemini-2.5-pro"
 *   DeepSeek: "deepseek/deepseek-chat", "deepseek/deepseek-r1"
 *   Grok:     "x-ai/grok-3", "x-ai/grok-4"
 *   Mistral:  "mistralai/mistral-small-3.2"
 *   Meta:     "meta-llama/llama-3.3-70b-instruct"
 *
 * Note: Image generation, TTS, STT, and video are puter.js SDK-only features.
 * Only text chat completions (with streaming SSE) are available via REST.
 */
export class PuterExecutor extends BaseExecutor {
  constructor() {
    super("puter", PROVIDERS["puter"] || { format: "openai" });
  }

  buildUrl(_model: string, _stream: boolean, _urlIndex = 0, _credentials = null): string {
    return "https://api.puter.com/puterai/openai/v1/chat/completions";
  }

  buildHeaders(credentials: any, stream = true): Record<string, string> {
    const headers: Record<string, string> = {
      "Content-Type": "application/json",
    };

    const key = credentials?.apiKey || credentials?.accessToken;
    if (key) {
      headers["Authorization"] = `Bearer ${key}`;
    }

    if (stream) {
      headers["Accept"] = "text/event-stream";
    }

    return headers;
  }

  transformRequest(model: string, body: any, _stream: boolean, _credentials: any): any {
    // Puter accepts model IDs directly from its catalog.
    // No transformation required — model string is passed as-is.
    return body;
  }
}

export default PuterExecutor;

